//! All47actual sources and accepted-animation action receipts, not seed representatives.
use ironsmith::{CardDefinition,GameState,PlayerId,Zone};use ironsmith::decision::{DecisionMaker,SelectFirstDecisionMaker};const A:PlayerId=PlayerId(0);
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-spellcharge-source-complete.json")).unwrap()}
fn definitions(name:&str)->[CardDefinition;2]{let data=fixture();let card=data["complete_sources"].as_array().unwrap().iter().find(|card|card["name"]==name).unwrap();let text=card["executable_text"].as_str().expect("every source requires a complete executable candidate");
 let vocabulary:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/source-subtypes.json")).unwrap();let vocabulary:Vec<ironsmith_core::custom_subtypes::CustomSubtypeDefinition>=vocabulary["definitions"].as_array().unwrap().iter().filter(|row|row["scope"]=="rev").map(|row|serde_json::from_value(row.clone()).unwrap()).collect();
 ironsmith_compiler::with_custom_subtypes(&vocabulary,||{let mut builder=ironsmith_compiler::CardDefinitionBuilder::new(ironsmith_compiler::ids::CardId::new(),name);if name!="Join the Forebears"{builder=builder.with_custom_keyword("spellcharge");}
 let(result,loss)=ironsmith_compiler::parse_loss::capture(||ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler::CompilerFacade::new().compile_definition(builder,text.to_string(),ironsmith_compiler::CompilePolicy{allow_unsupported:false})));assert!(!loss.is_lossy(),"{name}: {}",loss.reasons_text());let compiled=result.unwrap_or_else(|error|panic!("{name}: {error}"));let direct=ironsmith_compiler_runtime::into_runtime_definition(compiled.definition.clone()).unwrap();let wire=ironsmith_compiled_artifact::wire_definition_from_serializable(&compiled.definition).unwrap();let artifact=ironsmith_compiled_artifact::CompiledCardArtifact::new(ironsmith_compiled_artifact::ArtifactCardIdentity{local_id:ironsmith_compiled_artifact::ArtifactCardId(compiled.definition.card.id.0),name:name.into(),face_name:None,other_face:None,linked_face_layout:None},ironsmith_compiled_artifact::CompiledCardPayload{definition:wire,canonical_text:ironsmith_text::compiled_text_lines(&direct).join("\n"),ability_labels:ironsmith_text::ability_surface_texts(&direct)},"spellcharge-full-source",text.as_bytes());let decoded=ironsmith_compiled_artifact::CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();assert_eq!(artifact,decoded);[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&decoded).unwrap()]
 }).unwrap()
}
#[test]fn all47source_bodies_and47faces_compile_strictly_and_roundtrip(){let data=fixture();let cards=data["complete_sources"].as_array().unwrap();assert_eq!(cards.len(),47);for card in cards{assert_eq!(card["source_faces"].as_array().unwrap().len(),1);definitions(card["name"].as_str().unwrap());}}
struct Accept(bool);impl DecisionMaker for Accept{fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{self.0}}
fn cast_payment(game:&mut GameState,price:u32){use ironsmith::decision::{compute_legal_actions,LegalAction};let card=ironsmith_compiler_runtime::compile_to_runtime_definition("Actual spell payment",&format!("Mana cost: {{{price}}}\nType: Sorcery\nYou gain 1 life."),false).unwrap();let spell=game.create_object_from_definition(&card,A,Zone::Hand);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Colorless,price);let action=compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==spell)).unwrap();let mut state=ironsmith::game_loop::PriorityLoopState::new(2);let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=SelectFirstDecisionMaker;let mut progress=ironsmith::game_loop::apply_priority_response_with_dm(game,&mut queue,&mut state,&ironsmith::game_loop::PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){break}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("payment suspended outside typed choice")};progress=ironsmith::game_loop::apply_decision_context_with_dm(game,&mut queue,&mut state,&ctx,&mut dm).unwrap();}assert!(!state.has_pending_action());ironsmith::game_loop::resolve_stack_entry_with(game,&mut dm).unwrap();}
#[test]fn actual_chains_source_emits_only_accepted_spellcharge_then_untaps_from_its_trigger(){for definition in definitions("Chains of Broken Oaths"){for accept in [false,true]{let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);game.tap(source);game.take_pending_trigger_events();cast_payment(&mut game,2);cast_payment(&mut game,5);assert_eq!(game.turn_store.turn_history.mana_spent_to_cast_spells_this_turn[&A],7);game.take_pending_trigger_events();let mut queue=ironsmith::triggers::TriggerQueue::new();game.queue_trigger_event(Default::default(),ironsmith::triggers::TriggerEvent::new(ironsmith::events::BeginningOfCombatEvent::new(A),Default::default()));ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut SelectFirstDecisionMaker).unwrap();assert_eq!(queue.entries.len(),1);ironsmith::game_loop::put_triggers_on_stack(&mut game,&mut queue).unwrap();ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut Accept(accept)).unwrap();assert_eq!(game.current_has_card_type(source,ironsmith::CardType::Creature),accept);assert!(game.is_tapped(source));ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut SelectFirstDecisionMaker).unwrap();assert_eq!(queue.entries.len(),usize::from(accept));if accept{ironsmith::game_loop::put_triggers_on_stack(&mut game,&mut queue).unwrap();ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();assert!(!game.is_tapped(source));}ironsmith::turn::execute_cleanup_step(&mut game);assert!(!game.current_has_card_type(source,ironsmith::CardType::Creature));assert!(game.current_has_card_type(source,ironsmith::CardType::Artifact));}}}

#[test]fn actual_join_grants_a_copiable_creation_threshold_and_preserves_original_exile_and_types(){for definition in definitions("Join the Forebears"){
 let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;
 let original=ironsmith_compiler_runtime::compile_to_runtime_definition("Copied original","Mana cost: {4}\nType: Creature\nPower/Toughness: 3/4\nMenace",false).unwrap();let target=game.create_object_from_definition(&original,PlayerId(1),Zone::Battlefield);let target_stable=game.object(target).unwrap().stable_id;let source=game.create_object_from_definition(&definition,A,Zone::Hand);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Black,2);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Colorless,4);
 let action=ironsmith::decision::compute_legal_actions(&game,A).unwrap().into_iter().find(|action|matches!(action,ironsmith::decision::LegalAction::CastSpell{spell_id,..}if *spell_id==source)).unwrap();let mut state=ironsmith::game_loop::PriorityLoopState::new(2);let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=SelectFirstDecisionMaker;let mut progress=ironsmith::game_loop::apply_priority_response_with_dm(&mut game,&mut queue,&mut state,&ironsmith::game_loop::PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){break}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("actual Join announcement lost its target choice")};progress=ironsmith::game_loop::apply_decision_context_with_dm(&mut game,&mut queue,&mut state,&ctx,&mut dm).unwrap();}
 assert!(!state.has_pending_action());ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();let exiled=game.find_object_by_stable_id(target_stable).unwrap();assert_eq!(game.object(exiled).unwrap().zone,Zone::Exile);let token=*game.battlefield.iter().find(|id|game.object(**id).is_some_and(|object|object.kind==ironsmith::ObjectKind::Token)).unwrap();assert!(game.current_has_card_type(token,ironsmith::CardType::Artifact));assert!(!game.current_has_card_type(token,ironsmith::CardType::Creature));
 // A later mana-cost change cannot resample the granted value from4to9.
 game.object_mut(token).unwrap().mana_cost=Some(ironsmith::mana::ManaCost::from_symbols(vec![ironsmith::mana::ManaSymbol::Generic(9)]).into());assert_eq!(game.calculated_characteristics(token).unwrap().mana_cost.as_ref().map(|cost|cost.mana_value()),Some(9),"the later mana-cost change is visible before the frozen-threshold test");game.take_pending_trigger_events();game.queue_trigger_event(Default::default(),ironsmith::triggers::TriggerEvent::new(ironsmith::events::BeginningOfCombatEvent::new(A),Default::default()));ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut dm).unwrap();assert_eq!(queue.entries.len(),1,"the copied token's frozen4threshold is met by the actual6mana Join payment");ironsmith::game_loop::put_triggers_on_stack(&mut game,&mut queue).unwrap();ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut Accept(true)).unwrap();assert!(game.current_has_card_type(token,ironsmith::CardType::Creature));assert!(game.current_has_card_type(token,ironsmith::CardType::Artifact));assert_eq!(game.calculated_power(token),Some(3));
}}


#[test]
fn actual_aspect_modifies_opponent_loss_and_payment_once_without_changing_the_payment_receipt(){
 use ironsmith::effects::EffectExecutor;
 let b=PlayerId(1);
 for definition in definitions("Aspect of the End"){
  let mut game=GameState::new(vec!["A".into(),"B".into()],20);let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);let mut dm=SelectFirstDecisionMaker;
  let loss=ironsmith::effects::LoseLifeEffect::with_filter(3,ironsmith::target::PlayerFilter::Specific(b)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();
  assert_eq!(game.player(b).unwrap().life,16);assert_eq!(loss.events.iter().filter_map(|e|e.downcast::<ironsmith::events::LifeLossEvent>()).map(|e|e.amount).collect::<Vec<_>>(),vec![4],"one modified original loss, not a recursively replaced fresh loss");
  let payment=ironsmith::effects::PayLifeEffect::with_filter(2,ironsmith::target::PlayerFilter::Specific(b)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();assert_eq!(game.player(b).unwrap().life,13);
  assert_eq!(payment.events.iter().filter_map(|e|e.downcast::<ironsmith::events::LifePaidEvent>()).map(|e|e.amount).collect::<Vec<_>>(),vec![2],"CR119.4: original payment remains two; the resulting loss is increased");
  assert_eq!(payment.events.iter().filter_map(|e|e.downcast::<ironsmith::events::LifeLossEvent>()).map(|e|(e.amount,e.from_payment)).collect::<Vec<_>>(),vec![(3,true)]);
  ironsmith::effects::LoseLifeEffect::with_filter(3,ironsmith::target::PlayerFilter::Specific(A)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();assert_eq!(game.player(A).unwrap().life,17,"the controller is not their own opponent");
  ironsmith::effects::GainLifeEffect::with_filter(2,ironsmith::target::PlayerFilter::Specific(b)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();assert_eq!(game.player(b).unwrap().life,15,"the loss selector must not change life gain");
  ironsmith::effects::LoseLifeEffect::with_filter(0,ironsmith::target::PlayerFilter::Specific(b)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();assert_eq!(game.player(b).unwrap().life,15,"an absent zero-loss event cannot acquire an added loss");
  let independent=game.create_object_from_definition(&definition,A,Zone::Battlefield);
  ironsmith::effects::LoseLifeEffect::with_filter(2,ironsmith::target::PlayerFilter::Specific(b)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();assert_eq!(game.player(b).unwrap().life,11,"independent source replacements each apply once");
  game.object_mut(source).unwrap().abilities_mut().clear();game.object_mut(independent).unwrap().abilities_mut().clear();
  ironsmith::effects::LoseLifeEffect::with_filter(1,ironsmith::target::PlayerFilter::Specific(b)).execute(&mut game,&mut ironsmith::effects::EffectContext::new(source,A,&mut dm)).unwrap();assert_eq!(game.player(b).unwrap().life,10,"replacement exists only while the actual source ability exists");
 }
}
